// Original concise course text; references are linked for further study.
const choice=(id,label,options,answer=0)=>({id,type:'choice',label,options:options.map((text,i)=>({id:String(i),text})),answer:String(answer)});
const multi=(id,label,options,answer)=>({...choice(id,label,options),type:'multi',answer:answer.map(String)});
const number=(id,label,answer)=>({id,type:'number',label,answer,rule:'equal'});
const q=(id,chapter,title,prompt,parts,hint,explanation)=>({id,chapter,title,prompt,parts,hint,explanation});
const t=(title,body,formula)=>({title,body:'<p>'+body+'</p>',formula});
const ex=(title,statement,steps,result)=>({title,statement,steps,result});

export const ADVANCED_CHAPTERS=[
{id:'three',number:'03',title:'Интегральное исчисление',subtitle:'Первообразная, интеграл Римана, формула Ньютона — Лейбница и несобственные интегралы.',symbol:'∫ f(x) dx',card:'Интеграл одной переменной',prerequisites:'Нужны предел, непрерывность и производная функции одной переменной. Если эти понятия ещё не изучены, сначала разберите их в курсе первого семестра.',takeaway:'Определённый интеграл задаётся пределом интегральных сумм. Для непрерывной f на [a,b] его можно вычислить как F(b)−F(a), где F′=f. Несобственный интеграл определяется отдельным предельным переходом; существование первообразной не гарантирует его сходимость.',summaryFormula:'∫ₐᵇ f(x) dx = F(b) − F(a),  F′ = f',
theory:[
t('Первообразная и неопределённый интеграл','Функция F называется первообразной f на интервале I, если F дифференцируема на I и F′(x)=f(x) для всех x∈I. Любые две первообразные на одном интервале отличаются постоянной: это следует из теоремы Лагранжа. Неопределённый интеграл обозначает семейство всех первообразных, а не число. На несвязной области постоянные на разных компонентах могут различаться.','∫ f(x) dx = F(x)+C'),
t('Определение интеграла Римана','Пусть f ограничена на [a,b], a&lt;b. Разбиение задаётся точками a=x₀&lt;…&lt;xₙ=b, отмеченные точки ξᵢ выбираются в [xᵢ₋₁,xᵢ]. Число I называется интегралом Римана, если для каждого ε&gt;0 существует δ&gt;0: при максимальной длине части меньше δ любая интегральная сумма отличается от I меньше чем на ε. Требование относится ко всем отмеченным точкам и всем достаточно мелким разбиениям.','Σ f(ξᵢ)(xᵢ−xᵢ₋₁) → I при max Δxᵢ → 0'),
t('Критерий Дарбу и достаточные условия','Для каждой части разбиения обозначим через mᵢ и Mᵢ точную нижнюю и верхнюю границы f. Нижняя сумма L=ΣmᵢΔxᵢ, верхняя U=ΣMᵢΔxᵢ. Ограниченная функция интегрируема по Риману тогда и только тогда, когда для любого ε&gt;0 существует разбиение с U−L&lt;ε. В частности, непрерывная на отрезке функция интегрируема. Ограниченная функция с конечным числом разрывов также интегрируема.','∀ε&gt;0 ∃P: U(f,P)−L(f,P)&lt;ε'),
t('Основная теорема и формула Ньютона — Лейбница','Если f непрерывна на [a,b], то Φ(x)=∫ₐˣ f(t)dt дифференцируема внутри отрезка и Φ′(x)=f(x). Если F — любая первообразная f, то Φ−F постоянна и ∫ₐᵇf=F(b)−F(a). Следовательно, вычисление интеграла непрерывной функции сводится к нахождению первообразной. Перестановка пределов меняет знак; интеграл по вырожденному отрезку равен нулю.','d/dx ∫ₐˣ f(t)dt = f(x)'),
t('Замена переменной','Пусть φ∈C¹([α,β]), а f непрерывна на интервале, содержащем φ([α,β]). Применение правила производной сложной функции к первообразной f даёт формулу замены. Монотонность φ для этой формулы с ориентированными пределами не обязательна. При замене нужно изменить и дифференциал, и пределы.','∫ᵅᵝ f(φ(t))φ′(t)dt = ∫φ(α)φ(β) f(x)dx'),
t('Интегрирование по частям','Для u,v∈C¹([a,b]) интегрируем равенство (uv)′=u′v+uv′ и переносим одно слагаемое. Метод полезен, когда производная одного множителя упрощается, а другой легко интегрируется. Запись [uv]ₐᵇ означает u(b)v(b)−u(a)v(a).','∫ₐᵇ u v′ dx = [uv]ₐᵇ − ∫ₐᵇ u′v dx'),
t('Несобственные интегралы','Для функции, интегрируемой на каждом [a,R], интеграл по [a,+∞) определяется пределом при R→+∞. Он сходится, если предел конечен. Если особенность находится в правом конце b, используют предел ∫ₐᶜf при c→b−. При внутренней особенности c оба интеграла ∫ₐᶜf и ∫ᶜᵇf должны сходиться по отдельности. Например, симметрическое сокращение 1/x около нуля даёт главное значение, но не сходимость несобственного интеграла на [−1,1].','∫ₐ⁺∞ f(x)dx := lim R→∞ ∫ₐᴿ f(x)dx'),
t('Степенные эталоны и сравнение','Вычисление первообразной показывает: ∫₁⁺∞x⁻ᵖdx сходится ровно при p&gt;1; ∫₀¹x⁻ᵖdx — ровно при p&lt;1. Для неотрицательных функций 0≤f≤g сходимость ∫g влечёт сходимость ∫f; расходимость ∫f влечёт расходимость ∫g. Сходимость ∫|f| называется абсолютной и влечёт сходимость ∫f. Обратное неверно.','∫₁⁺∞ dx/xᵖ &lt; ∞ ⇔ p&gt;1')],
workedExamples:[ex('Замена переменной','Вычислить ∫₀¹ 2x/(1+x²) dx.',['Положим u=1+x², du=2x dx. При x=0 получаем u=1, при x=1 — u=2.','Интеграл равен ∫₁² du/u=[ln u]₁².'],'ln 2'),ex('Интегрирование по частям','Вычислить ∫₀¹ x eˣ dx.',['Берём u=x, v′=eˣ. Тогда u′=1, v=eˣ.','[xeˣ]₀¹−∫₀¹eˣdx=e−(e−1).'],'1'),ex('Проверка сходимости','Исследовать ∫₁⁺∞x⁻ᵖdx.',['При p≠1 интеграл до R равен (R¹⁻ᵖ−1)/(1−p).','Если p>1, R¹⁻ᵖ→0 и предел равен 1/(p−1). При p<1 выражение растёт без границы.','При p=1 интеграл равен ln R→+∞.'],'Сходится ровно при p>1.')],deep:'Почему первообразные отличаются постоянной. Если F′=G′=f на интервале I, то (F−G)′=0. Для любых x<y из I теорема Лагранжа даёт (F−G)(y)−(F−G)(x)=0·(y−x)=0. Поэтому F−G постоянна на всём I.',sources:[['OpenStax: основная теорема анализа','https://openstax.org/books/calculus-volume-2/pages/1-3-the-fundamental-theorem-of-calculus'],['OpenStax: несобственные интегралы','https://openstax.org/books/calculus-volume-2/pages/3-7-improper-integrals']]},

{id:'four',number:'04',title:'Функции нескольких переменных',subtitle:'Предел, дифференциал, градиент, матрица Якоби, неявная функция и экстремумы.',symbol:'df = ∇f · dx',card:'Дифференцирование в ℝⁿ',prerequisites:'Используются предел и производная одной переменной, векторы, скалярное произведение, матрицы и определители.',takeaway:'Дифференцируемость означает существование линейного приближения с остатком o(‖h‖). Существование частных производных само по себе недостаточно. При дифференцируемости все производные по направлениям определяются одним линейным отображением — дифференциалом.',summaryFormula:'f(a+h) = f(a)+Df(a)h+o(‖h‖)',
theory:[t('Предел в ℝⁿ','Предел f(x) при x→a равен L, если для каждого ε&gt;0 существует δ&gt;0: из 0&lt;‖x−a‖&lt;δ следует |f(x)−L|&lt;ε. Условие должно выполняться при всех направлениях приближения. Совпадение пределов вдоль нескольких прямых не доказывает существования общего предела. У xy/(x²+y²) при (x,y)→(0,0) вдоль осей предел 0, а вдоль y=x — 1/2.','0&lt;‖x−a‖&lt;δ ⇒ |f(x)−L|&lt;ε'),
t('Частные производные','Частная производная по xᵢ — производная по одной координате при фиксированных остальных. Её существование в точке описывает лишь приращения вдоль соответствующей оси. Продолжим предыдущую функцию нулём в начале координат: обе частные производные там равны нулю, но функция даже не непрерывна.','∂ᵢf(a) = lim t→0 [f(a+teᵢ)−f(a)]/t'),
t('Дифференцируемость и полный дифференциал','Функция f:U⊆ℝⁿ→ℝᵐ, U открыто, дифференцируема в a, если существует линейное отображение Df(a), для которого остаток после линейного приближения есть o(‖h‖). Дифференцируемость влечёт непрерывность и существование частных производных. Достаточное условие: частные производные существуют в окрестности a и непрерывны в a.','f(a+h)−f(a) = Df(a)h+o(‖h‖)'),
t('Градиент и производная по направлению','Для скалярной дифференцируемой f градиент — вектор её частных производных. Для единичного v производная по направлению равна ∇f(a)·v. По неравенству Коши — Буняковского наибольшее значение равно ‖∇f(a)‖ и при ненулевом градиенте достигается на v=∇f/‖∇f‖. Для неединичного вектора параметризация имеет другую скорость.','Dᵥf(a)=∇f(a)·v,  ‖v‖=1'),
t('Матрица Якоби и правило цепочки','Матрица Якоби Jf содержит в строке i частные производные компоненты fᵢ. Для f:ℝⁿ→ℝᵐ её размер m×n. Если f дифференцируема в a, а g — в f(a), то композиция дифференцируема и её матрица получается умножением в указанном порядке. Определитель Якоби определён для квадратной матрицы.','J(g∘f)(a)=Jg(f(a)) Jf(a)'),
t('Второй дифференциал и формула Тейлора','Для f∈C² в окрестности a смешанные вторые производные совпадают; матрица Гессе Hf симметрична. Квадратичное приближение уточняет линейное с остатком o(‖h‖²). Условие непрерывности вторых производных — достаточное условие равенства смешанных производных, его нельзя просто опустить.','f(a+h)=f(a)+∇f(a)·h+½hᵀHf(a)h+o(‖h‖²)'),
t('Локальные экстремумы','Во внутренней точке дифференцируемого локального экстремума ∇f=0. Обратное неверно. Для C²-функции в стационарной точке положительно определённый Гессиан даёт строгий минимум, отрицательно определённый — строгий максимум, неопределённый — седловую точку. Полуопределённый Гессиан общего ответа не даёт: нужны члены более высокого порядка или иной анализ.','x²+y²: минимум; −x²−y²: максимум; x²−y²: седло'),
t('Теорема о неявной функции','Пусть F∈C¹ в окрестности (a,b), F(a,b)=0 и Fᵧ(a,b)≠0. Тогда в некоторых окрестностях уравнение F(x,y)=0 однозначно задаёт C¹-функцию y=φ(x), φ(a)=b. Дифференцирование тождества даёт φ′=−Fₓ/Fᵧ вдоль графика. Вывод локальный, он не утверждает существования одной функции y(x) на всей кривой.','φ′(x)=−Fₓ(x,φ(x))/Fᵧ(x,φ(x))'),
t('Условный экстремум и множители Лагранжа','Для C¹-функций f,g при условии g(x)=0 и ∇g(a)≠0 необходимое условие локального условного экстремума: ∇f(a)=λ∇g(a) для некоторого λ. Решения этой системы — кандидаты, а не автоматически экстремумы. На компактном множестве непрерывная f достигает глобальных минимума и максимума; сравнивают все кандидаты, учитывая нерегулярные точки и границу, если они есть.','∇f=λ∇g,  g=0')],
workedExamples:[ex('Полный дифференциал','f(x,y)=x²y+3y²; точка (1,2).',['fₓ=2xy, fᵧ=x²+6y. В точке получаем 4 и 13.','df=4 dx+13 dy. Следовательно, f(1+h,2+k)=14+4h+13k+o(√(h²+k²)).'],'df(1,2)=4 dx+13 dy'),ex('Неявная производная','x²+y²=25 в окрестности (3,4).',['Fᵧ=2y=8≠0, поэтому локальная функция y(x) существует.','y′=−2x/(2y)=−x/y; подставляем (3,4).'],'y′(3)=−3/4'),ex('Условный максимум','Максимизировать x+y при x²+y²=1.',['(1,1)=λ(2x,2y), значит x=y.','Получаем точки (1/√2,1/√2) и (−1/√2,−1/√2). Окружность компактна.','Значения равны √2 и −√2; сравнение даёт оба глобальных экстремума.'],'max=√2, min=−√2')],deep:'Дифференцируемость влечёт непрерывность. Из f(a+h)−f(a)=Lh+o(‖h‖) и ограниченности линейного отображения в конечномерном пространстве следует ‖f(a+h)−f(a)‖≤C‖h‖+o(‖h‖)→0. Поэтому пример с существующими частными производными, но без непрерывности заведомо не дифференцируем.',sources:[['OpenStax: частные производные','https://openstax.org/books/calculus-volume-3/pages/4-3-partial-derivatives'],['OpenStax: множители Лагранжа','https://openstax.org/books/calculus-volume-3/pages/4-8-lagrange-multipliers']]},

{id:'five',number:'05',title:'Функциональные последовательности и ряды',subtitle:'Поточечная и равномерная сходимость, степенные ряды, ряд Тейлора и ряды Фурье.',symbol:'sup |fₙ−f| → 0',card:'Пределы и функциональные ряды',prerequisites:'Нужны числовые последовательности и ряды, признаки сходимости, предел, производная и определённый интеграл.',takeaway:'При поточечной сходимости номер N может зависеть от точки. При равномерной один N подходит для всей области. Именно дополнительные условия на сходимость позволяют переносить непрерывность и менять порядок предела с интегрированием или дифференцированием.',summaryFormula:'fₙ ⇒ f на E ⇔ supₓ∈E |fₙ(x)−f(x)| → 0',
theory:[t('Поточечная и равномерная сходимость','Последовательность fₙ:E→ℝ сходится поточечно к f, если для каждого x∈E числовая последовательность fₙ(x) сходится к f(x). В ε-определении N может зависеть от x. При равномерной сходимости N зависит от ε, но один и тот же для всех x∈E. Эквивалентная запись использует точную верхнюю границу ошибки, которая может не достигаться.','Поточечно: ∀x ∀ε>0 ∃N ∀n≥N. Равномерно: ∀ε>0 ∃N ∀x ∀n≥N.'),
t('Пример xⁿ','На [0,1] поточечный предел xⁿ равен 0 при x&lt;1 и 1 при x=1. Для каждого n точная верхняя граница ошибки равна 1: при x→1− величина xⁿ стремится к 1, хотя в самой точке 1 ошибка нулевая. Поэтому равномерной сходимости нет. На [0,b] при 0&lt;b&lt;1 предел всюду нулевой и sup xⁿ=bⁿ→0, то есть сходимость равномерна.','sup₀≤x≤b xⁿ=bⁿ →0 при b<1'),
t('Непрерывность и интегрирование предела','Равномерный предел непрерывных функций непрерывен. Если fₙ интегрируемы по Риману на [a,b] и сходятся равномерно к f, то f также интегрируема, а интегралы сходятся к интегралу f. Доказательство оценки опирается на |∫(fₙ−f)|≤(b−a)sup|fₙ−f|. Одна поточечная сходимость этих заключений не обеспечивает.','∫ₐᵇ lim fₙ = lim ∫ₐᵇ fₙ  при равномерной сходимости'),
t('Дифференцирование предела','Достаточная теорема: пусть fₙ∈C¹([a,b]), последовательность fₙ(x₀) сходится хотя бы в одной точке, а fₙ′ равномерно сходится к g на [a,b]. Тогда fₙ равномерно сходится к некоторой f, причём f′=g внутри отрезка. Равномерной сходимости самих fₙ недостаточно для перехода к пределу под производной: например, sin(nx)/n→0 равномерно, а производные cos(nx) не сходятся поточечно на всём отрезке [0,2π].','lim fₙ′ = (lim fₙ)′ — только при дополнительных условиях'),
t('Функциональный ряд и признак Вейерштрасса','Ряд Σuₙ(x) — последовательность частичных сумм Sₙ(x). Его сходимость определяется сходимостью Sₙ. Если на E выполнено |uₙ(x)|≤Mₙ и числовой ряд ΣMₙ сходится, то функциональный ряд сходится абсолютно в каждой точке и равномерно на E. Непрерывные слагаемые тогда дают непрерывную сумму. Расходимость выбранного ряда мажорант сама по себе ничего не доказывает.','|uₙ(x)|≤Mₙ, ΣMₙ<∞ ⇒ Σuₙ сходится равномерно'),
t('Степенные ряды','Для Σaₙ(x−x₀)ⁿ существует радиус R∈[0,+∞]. Внутри |x−x₀|&lt;R ряд сходится абсолютно и равномерно на каждом замкнутом отрезке, лежащем внутри интервала сходимости. За его пределами ряд расходится. При |x−x₀|=R каждую конечную граничную точку исследуют отдельно. Внутри радиуса разрешены почленное дифференцирование и интегрирование; радиус при этом сохраняется.','1/R = limsup |aₙ|¹⁄ⁿ;  1/0=∞, 1/∞=0'),
t('Ряд Тейлора и остаток','Коэффициенты ряда Тейлора в точке a равны f⁽ⁿ⁾(a)/n!. Формула Тейлора конечного порядка содержит остаток. Равенство функции бесконечному ряду требует стремления остатка к нулю. Бесконечная дифференцируемость сама по себе этого не гарантирует. Например, функция e^(−1/x²) при x≠0, продолженная нулём в 0, имеет все производные в 0 равными нулю, но положительна при x≠0.','f(x)=Σₙ₌₀∞ f⁽ⁿ⁾(a)(x−a)ⁿ/n! ⇔ Rₙ(x)→0'),
t('Коэффициенты Фурье','Для интегрируемой 2π-периодической функции коэффициенты определяют интегралами на [−π,π]. Используем соглашение f∼a₀/2+Σₙ≥₁(aₙcos nx+bₙsin nx). Для чётной f коэффициенты bₙ нулевые; для нечётной — все aₙ нулевые. Символ ∼ здесь обозначает соответствующий ряд, а не утверждение его поточечной сходимости к f.','aₙ=(1/π)∫₋ππ f(x)cos(nx)dx; bₙ=(1/π)∫₋ππ f(x)sin(nx)dx'),
t('Сходимость Фурье и равенство Парсеваля','Достаточное условие Дирихле: 2π-периодическая функция кусочно C¹ с конечным числом участков и конечными односторонними пределами. Тогда ряд в точке x сходится к (f(x−)+f(x+))/2; в точке непрерывности — к f(x). При скачке непрерывные частичные суммы не могут сходиться равномерно на всём периоде. Для f∈L²(−π,π) равенство Парсеваля выражает квадрат L²-нормы через коэффициенты. Поточечная сходимость и сходимость в L² — разные утверждения.','(1/π)∫₋ππ |f|² dx = a₀²/2 + Σₙ≥₁(aₙ²+bₙ²)')],
workedExamples:[ex('Равномерная оценка','fₙ(x)=x/n на [0,1].',['Поточечный предел равен нулю.','supₓ∈[0,1]|x/n|=1/n→0. Для ε>0 достаточно взять N>1/ε.'],'Сходимость равномерна.'),ex('Граничные точки степенного ряда','Σₙ≥₁ xⁿ/n.',['По формуле радиуса R=1.','При x=1 получается гармонический ряд, который расходится.','При x=−1 получается знакочередующийся ряд Σ(−1)ⁿ/n, сходящийся по признаку Лейбница, но не абсолютно.'],'Интервал сходимости [−1,1).'),ex('Фурье для f(x)=x','На (−π,π) задана f(x)=x; продолжение 2π-периодическое.',['Функция нечётна, поэтому a₀=aₙ=0.','По частям: ∫₋ππ x sin(nx)dx=−2π(−1)ⁿ/n; значит bₙ=2(−1)ⁿ⁺¹/n.','Внутри (−π,π) ряд сходится к x. В точках ±π сумма равна полусумме пределов (π−π)/2=0.'],'x = 2Σₙ≥₁ (−1)ⁿ⁺¹ sin(nx)/n при −π<x<π.')],deep:'Почему равномерный предел непрерывен. Для точки a выбираем один номер n так, чтобы |f−fₙ|<ε/3 на всей области. По непрерывности этой fₙ при x достаточно близком к a имеем |fₙ(x)−fₙ(a)|<ε/3. Неравенство треугольника даёт |f(x)−f(a)|<ε. При поточечной сходимости общего номера для двух переменных точек может не быть.',sources:[['MIT: лекции о равномерной сходимости и степенных рядах','https://ocw.mit.edu/courses/18-100a-real-analysis-fall-2020/pages/lecture-notes-and-readings/'],['MIT: анализ Фурье','https://ocw.mit.edu/courses/18-103-fourier-analysis-fall-2013/']]},

{id:'six',number:'06',title:'Многомерное интегрирование',subtitle:'Кратные, криволинейные и поверхностные интегралы. Формулы Грина, Стокса и Гаусса.',symbol:'∫∫∫ f dV',card:'Интегралы и ориентация',prerequisites:'Нужны главы 03–04, векторное и скалярное произведения, параметризация кривых и поверхностей.',takeaway:'При замене координат элемент объёма умножается на модуль якобиана. В интегралах первого рода учитывается длина или площадь; в циркуляции и потоке существенна ориентация. Формулы Грина, Стокса и Гаусса применяются при указанных условиях гладкости и согласованной ориентации.',summaryFormula:'dV = |det JΦ| du;  ∯∂V F·n dS = ∭V div F dV',
theory:[t('Двойной и тройной интегралы','Кратный интеграл Римана определяется пределом сумм f(ξᵢ)ΔVᵢ по мелким разбиениям области; ΔVᵢ — площадь в ℝ² или объём в ℝ³. Для ограниченной области, измеримой по Жордану, непрерывная на её замыкании функция интегрируема. Интеграл единицы даёт площадь или объём. Эти достаточные условия не описывают все интегрируемые функции.','∬D 1 dA = площадь D; ∭V 1 dV = объём V'),
t('Повторные интегралы и порядок интегрирования','Для непрерывной f на прямоугольнике теорема Фубини позволяет вычислять двойной интеграл в любом порядке. Для области a≤x≤b, α(x)≤y≤β(x) с непрерывными границами и непрерывной f на замыкании получаем повторный интеграл с переменными внутренними пределами. Смена порядка требует заново описать ту же область неравенствами.','∬D f dA = ∫ₐᵇ [∫α(x)β(x) f(x,y)dy]dx'),
t('Замена координат и якобиан','Для C¹-диффеоморфизма Φ между открытыми областями и интегрируемой функции применяется формула замены с |det JΦ|. Модуль обязателен для площади и объёма. Полярные координаты x=r cosθ, y=r sinθ дают якобиан r при r≥0. В полярной формуле точку r=0 и выбранный разрез можно обработать как множества нулевой площади; на всей области с включённым нулём отображение не является диффеоморфизмом.','∬D f(x,y)dxdy = ∬G f(Φ(u,v)) |det JΦ(u,v)| dudv'),
t('Цилиндрические и сферические координаты','Цилиндрические координаты (r,θ,z) имеют элемент объёма r dr dθ dz. В сферических используем ρ≥0, полярный угол φ∈[0,π] от положительной оси z и азимут θ∈[0,2π): x=ρsinφcosθ, y=ρsinφsinθ, z=ρcosφ. Якобиан равен ρ²sinφ. Пределы задаются геометрией области, а соглашение об углах нужно указывать.','dV = ρ² sinφ dρ dφ dθ'),
t('Криволинейный интеграл первого рода','Пусть γ задана кусочно C¹-регулярной параметризацией r:[a,b]→ℝⁿ. Интеграл скалярной f по длине вычисляется с множителем ‖r′(t)‖. Он не меняется при смене ориентации. В частности, интеграл единицы даёт длину кривой. При повторном прохождении участка параметрический интеграл учитывает его кратность.','∫γ f ds = ∫ₐᵇ f(r(t)) ‖r′(t)‖ dt'),
t('Циркуляция и потенциальное поле','Криволинейный интеграл второго рода равен ∫F(r(t))·r′(t)dt и меняет знак при обращении ориентации. Если F=∇φ, он равен φ(B)−φ(A). Для C¹-поля в открытой односвязной области ℝ² условие Qₓ=Pᵧ достаточно для существования потенциала. Без условия на область вывод неверен: у поля (−y/(x²+y²),x/(x²+y²)) вне нуля циркуляция по единичной окружности равна 2π.','∫γ ∇φ·dr = φ(B)−φ(A)'),
t('Формула Грина','Пусть D — ограниченная плоская область с кусочно гладкой границей, а P,Q∈C¹ в окрестности её замыкания. Положительная ориентация означает, что область остаётся слева: внешняя граница обходится против часовой стрелки, внутренние границы — по часовой. Циркуляция по границе выражается двойным интегралом.','∮∂D P dx+Q dy = ∬D (Qₓ−Pᵧ) dxdy'),
t('Поверхностные интегралы и поток','Для регулярной параметризации r(u,v) элемент площади равен ‖rᵤ×rᵥ‖du dv. В интеграле первого рода используют этот неотрицательный множитель. Поток F через ориентированную поверхность использует вектор rᵤ×rᵥ, выбранный в согласии с нормалью; обращение нормали меняет знак. Для нескольких карт интегрируют по частям поверхности без двойного счёта.','∬S F·n dS = ∬G F(r(u,v))·(rᵤ×rᵥ) du dv'),
t('Формула Стокса','Для ориентированной кусочно гладкой поверхности S с кусочно гладкой границей и C¹-поля F в её окрестности циркуляция по границе равна потоку ротора. Ориентация границы согласована с нормалью по правилу правого винта. Для плоского диска с нормалью вверх граница обходится против часовой стрелки при взгляде сверху. Для обычной классической формулировки достаточно кусочно C²-регулярных карт поверхности.','∮∂S F·dr = ∬S (rot F)·n dS'),
t('Формула Гаусса — Остроградского','Пусть V — ограниченное тело с кусочно гладкой замкнутой границей, F∈C¹ в окрестности замыкания V. Поток через всю границу с внешней нормалью равен тройному интегралу дивергенции. Для внутренней полости внешняя нормаль тела направлена в полость. Формула не применима напрямую, если поле имеет особенность внутри тела.','∯∂V F·n dS = ∭V div F dV')],
workedExamples:[ex('Повторное интегрирование','∫₀¹∫₀²(x+y)dy dx.',['Внутренний интеграл: [xy+y²/2]₀²=2x+2.','Внешний: [x²+2x]₀¹=3.'],'3'),ex('Площадь в полярных координатах','Кольцевой сектор a≤r≤2, 0≤θ≤α, 0≤a<2, 0<α≤2π.',['Подынтегральная функция для площади равна 1, но dxdy=r drdθ.','∫₀ᵅ∫ₐ²r drdθ=α(4−a²)/2.'],'Площадь α(4−a²)/2.'),ex('Ориентация в формуле Грина','F=(−y,x), единичная окружность против часовой стрелки.',['Qₓ−Pᵧ=1−(−1)=2.','Интеграл равен ∫∫диск 2 dA=2π.','При обходе по часовой стрелке знак меняется.'],'2π; при обратном обходе −2π.'),ex('Поток через сферу','F=(x,y,z), единичная сфера, внешняя нормаль.',['Поле гладко во всём шаре, div F=3.','По Гауссу поток равен 3·(4π/3).'],'4π')],deep:'Грин как плоский случай Стокса. Для F=(P,Q,0) и поверхности в плоскости z=0 с нормалью (0,0,1) скалярное произведение rot F с нормалью равно Qₓ−Pᵧ. Поверхностный элемент равен dxdy, а согласованный обход положителен. Поэтому формула Стокса принимает вид формулы Грина.',sources:[['OpenStax: формула Грина','https://openstax.org/books/calculus-volume-3/pages/6-4-greens-theorem'],['OpenStax: формула Стокса','https://openstax.org/books/calculus-volume-3/pages/6-7-stokes-theorem'],['OpenStax: формула Гаусса','https://openstax.org/books/calculus-volume-3/pages/6-8-the-divergence-theorem']]}
];

export const ADVANCED_PRACTICE=[
q('l3-1','three','Семейство первообразных','f(x)=3x² на ℝ.',[choice('a','Все первообразные f',['x³+C','6x+C','x³','3x³+C'])],'Продифференцируйте каждый вариант.','(x³+C)′=3x² при любой постоянной C. Одна x³ — лишь одна первообразная.'),
q('l3-2','three','Ньютон — Лейбниц','Вычислите ∫₀²3x² dx.',[number('a','Значение интеграла',8)],'Первообразная равна x³.','[x³]₀²=8−0=8.'),
q('l3-3','three','Подстановка','Вычислите ∫₀¹ 2x/(1+x²) dx.',[choice('a','Точное значение',['ln 2','2 ln 2','1/2','1'])],'Положите u=1+x².','du=2x dx, новые пределы 1 и 2. ∫₁²du/u=ln 2.'),
q('l3-4','three','По частям','Вычислите ∫₀¹xeˣ dx.',[number('a','Значение',1)],'u=x, v′=eˣ.','[xeˣ]₀¹−[eˣ]₀¹=e−(e−1)=1.'),
q('l3-5','three','Сходимость у разных концов','Выберите все сходящиеся несобственные интегралы.',[multi('a','Сходятся',['∫₁⁺∞x⁻²dx','∫₀¹x⁻¹⁄²dx','∫₁⁺∞dx/x','∫₀¹dx/x²'],[0,1])],'Сравните показатели с 1 отдельно для нуля и бесконечности.','На бесконечности нужен p>1, около нуля p<1. Первые два интеграла равны 1 и 2.'),
q('l4-1','four','Частные производные','f(x,y)=x²y+3y². Точка (1,2).',[number('a','fₓ(1,2)',4),number('b','fᵧ(1,2)',13)],'При дифференцировании по одной переменной другую фиксируют.','fₓ=2xy=4; fᵧ=x²+6y=13.'),
q('l4-2','four','Производная по направлению','f(x,y)=x²+2y², a=(1,1), v=(1,0).',[number('a','Dᵥf(a)',2)],'v единичный; вычислите ∇f(a)·v.','∇f=(2x,4y), в точке (1,1) это (2,4). (2,4)·(1,0)=2.'),
q('l4-3','four','Якобиан','Φ(x,y)=(x²,xy).',[number('a','det JΦ(1,2)',2)],'Первая строка матрицы (2x,0), вторая (y,x).','Определитель равен 2x², поэтому в (1,2) он равен 2.'),
q('l4-4','four','Стационарная точка','Исследуйте f(x,y)=x²+y² в (0,0).',[choice('a','Классификация',['Строгий глобальный минимум','Строгий максимум','Седловая точка','Экстремума нет'])],'Сравните f(x,y) с f(0,0).','x²+y²>0 вне начала координат и f(0,0)=0. Гессиан diag(2,2) положительно определён.'),
q('l4-5','four','Неявная функция','x²+y²=25; локальная ветвь через (3,4).',[number('a','y′ при x=3',-.75)],'Дифференцируйте x²+y(x)²=25.','2x+2yy′=0. Так как y=4≠0, y′=−x/y=−3/4.'),
q('l5-1','five','Предел xⁿ','fₙ(x)=xⁿ на [0,1].',[choice('a','Какова сходимость?',['Поточечная, но не равномерная','Равномерная к нулю','Равномерная к разрывной функции','Поточечной сходимости нет'])],'Вычислите предел отдельно при x<1 и x=1.','Предел равен 0 при x<1 и 1 при x=1; sup ошибки равен 1 для каждого n.'),
q('l5-2','five','Оценка равномерной ошибки','fₙ(x)=x/n на [0,1].',[number('a','sup |f₄−0|',.25),choice('b','Сходимость',['Равномерная к 0','Только поточечная','Не сходится'])],'Максимум x/n достигается при x=1.','sup|fₙ|=1/n→0; для n=4 ошибка 1/4.'),
q('l5-3','five','Радиус и граница','Ряд Σₙ₌₀∞xⁿ.',[number('a','Радиус сходимости',1),choice('b','Что происходит при x=−1 и x=1?',['В обеих точках расходится','В обеих сходится','Сходится только в −1'])],'Необходимое условие сходимости: слагаемое стремится к нулю.','При |x|<1 сумма 1/(1−x). В обеих граничных точках слагаемые не стремятся к нулю.'),
q('l5-4','five','Признак Вейерштрасса','uₙ(x)=sin(nx)/n² на ℝ.',[choice('a','Какое утверждение следует из |uₙ|≤1/n²?',['Ряд сходится абсолютно и равномерно на ℝ','Только поточечно','Ряд расходится','Сумма обязательно дифференцируема'])],'Числовой ряд Σ1/n² сходится.','Признак Вейерштрасса даёт абсолютную и равномерную сходимость. Утверждение о производной из этой оценки не следует.'),
q('l5-5','five','Коэффициенты Фурье','f(x)=x на (−π,π), 2π-периодическое продолжение.',[number('a','b₁',2),choice('b','Косинусные коэффициенты aₙ',['Все равны нулю','Все равны 1','aₙ=2/n'])],'Используйте нечётность и интегрирование по частям.','aₙ=0 по нечётности; bₙ=2(−1)ⁿ⁺¹/n, поэтому b₁=2.'),
q('l6-1','six','Повторный интеграл','Вычислите ∫₀¹∫₀²(x+y)dy dx.',[number('a','Значение',3)],'Сначала интегрируйте по y, считая x постоянным.','Внутренний интеграл 2x+2; внешний [x²+2x]₀¹=3.'),
q('l6-2','six','Полярные координаты','Площадь диска x²+y²≤4.',[choice('a','Элемент площади',['r dr dθ','dr dθ','r² dr dθ']),number('b','Коэффициент при π в площади',4)],'0≤r≤2, 0≤θ≤2π.','∫₀²π∫₀²r drdθ=2π·2=4π.'),
q('l6-3','six','Потенциальное поле','F=(2x,2y). Интеграл по любой кусочно гладкой кривой из (0,0) в (1,2).',[number('a','∫γ F·dr',5)],'Потенциал φ=x²+y².','Интеграл равен φ(1,2)−φ(0,0)=1+4=5.'),
q('l6-4','six','Гаусс — Остроградский','F=(x,y,z), единичная сфера с внешней нормалью.',[number('a','Коэффициент при π в потоке',4)],'div F=3, объём шара 4π/3.','Поток равен 3·4π/3=4π.'),
q('l6-5','six','Грин и ориентация','F=(−y,x), единичная окружность против часовой стрелки.',[number('a','Коэффициент при π в циркуляции',2),choice('b','При обращении обхода интеграл…',['меняет знак','сохраняется','становится нулём'])],'Qₓ−Pᵧ=2.','Циркуляция равна 2·площадь диска=2π. При обратном обходе получаем −2π.')
];

